<label class="<?= $field('roll_no_original') ?>">Enrollment / Roll Number<input name="roll_no_original" value="<?= e($values['roll_no_original']??'') ?>" placeholder="245UCS005" required><?php if(isset($errors['roll_no_original'])):?><b><?= e($errors['roll_no_original']) ?></b><?php endif;?></label>
