<label class="<?= $field('name') ?>">Full Name<input name="name" value="<?= e($values['name']??'') ?>" required><?php if(isset($errors['name'])):?><b><?= e($errors['name']) ?></b><?php endif;?></label>
<label class="<?= $field('mobile_number') ?>">Mobile Number<input name="mobile_number" value="<?= e($values['mobile_number']??'') ?>" inputmode="tel" maxlength="20" required><?php if(isset($errors['mobile_number'])):?><b><?= e($errors['mobile_number']) ?></b><?php endif;?></label>
<label class="<?= $field('address') ?>">Address<textarea name="address" rows="3" required><?= e($values['address']??'') ?></textarea><?php if(isset($errors['address'])):?><b><?= e($errors['address']) ?></b><?php endif;?></label>
</div></section>
<section class="panel form-section"><div class="form-section-heading"><p class="eyebrow">Academic placement</p><h2>School, department and branch</h2></div><div class="form-grid two">
