<label class="<?= $field('branch') ?>">Branch<input name="branch" value="<?= e($values['branch']??'') ?>" required><?php if(isset($errors['branch'])):?><b><?= e($errors['branch']) ?></b><?php endif;?></label>
<label class="<?= $field('department_name') ?>">Department<input name="department_name" value="<?= e($values['department_name']??'') ?>" required><?php if(isset($errors['department_name'])):?><b><?= e($errors['department_name']) ?></b><?php endif;?></label>
<label class="<?= $field('school_name') ?>">School<input name="school_name" value="<?= e($values['school_name']??'') ?>" required><?php if(isset($errors['school_name'])):?><b><?= e($errors['school_name']) ?></b><?php endif;?></label>
<label class="<?= $field('current_year_of_study') ?>">Current Year of Study<select name="current_year_of_study" required><option value="">Select year</option><?php for($year=1;$year<=8;$year++):?><option value="<?= $year ?>" <?= (int)($values['current_year_of_study']??0)===$year?'selected':'' ?>>Year <?= $year ?></option><?php endfor;?></select><?php if(isset($errors['current_year_of_study'])):?><b><?= e($errors['current_year_of_study']) ?></b><?php endif;?></label>
<label class="<?= $field('semester') ?>">Current Semester<select name="semester" required><option value="">Select semester</option><?php for($semester=1;$semester<=12;$semester++):?><option value="<?= $semester ?>" <?= (int)($values['semester']??0)===$semester?'selected':'' ?>>Semester <?= $semester ?></option><?php endfor;?></select><?php if(isset($errors['semester'])):?><b><?= e($errors['semester']) ?></b><?php endif;?></label>
